import React, { useState, useEffect } from 'react';
import api from '../services/api';
import { useTheme } from '../context/ThemeContext';

const Dashboard = () => {
  const theme = useTheme();
  const [stats, setStats] = useState({
    students: 0,
    teachers: 0,
    payments: 0,
    attendance: 0,
  });
  const [recentStudents, setRecentStudents] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchStats();
  }, []);

 const fetchStats = async () => {
  try {
    const token = localStorage.getItem('access_token');
    console.log('Dashboard - Token:', token);
    
    const [studentsRes, teachersRes, feesRes, attendanceRes, recentStudentsRes] = await Promise.all([
      api.get('/api/students/count'), // Added trailing slash before ?
      api.get('/api/teachers/count'), // Added trailing slash before ?
      api.get('/api/fees/count'),     // Added trailing slash before ?
      api.get('/api/attendance/?limit=100'), // Added trailing slash before ?
      api.get('/api/students/?limit=5&skip=0'),
      
    ]);

    console.log('Students response:', studentsRes.data);  // Add this for debugging
    console.log('Teachers response:', teachersRes.data);  // Add this for debugging
    console.log('Fees response:', feesRes.data);          // Add this for debugging

    // Calculate attendance percentage
    let attendancePercent = 0;
    if (attendanceRes.data && attendanceRes.data.length > 0) {
      const present = attendanceRes.data.filter(a => a.status === 'present').length;
      attendancePercent = Math.round((present / attendanceRes.data.length) * 100);
    }

    setStats({
      students: studentsRes.data.count || 0,
      teachers: teachersRes.data.count || 0,
      payments: feesRes.data.count || 0,
      attendance: attendancePercent,
    });

    setRecentStudents(recentStudentsRes.data || []);

  } catch (error) {
    console.error('Failed to fetch stats:', error);
    setStats({
      students: 0,
      teachers: 0,
      payments: 0,
      attendance: 0,
    });
    setRecentStudents([]);
  } finally {
    setLoading(false);
  }
};



  const cards = [
    { title: 'Students', value: stats.students, icon: '👨‍🎓', color: 'bg-blue-500' },
    { title: 'Teachers', value: stats.teachers, icon: '👨‍🏫', color: 'bg-green-500' },
    { title: 'Total Payments', value: `$${stats.payments}`, icon: '💰', color: 'bg-amber-500' },
    { title: 'Attendance Rate', value: `${stats.attendance}%`, icon: '📊', color: 'bg-purple-500' },
  ];

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary"></div>
      </div>
    );
  }

  return (
    <div>
      <h1 className="text-3xl font-bold text-gray-800 mb-6">Dashboard</h1>

      {/* Stats Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-6">
        {cards.map((card) => (
          <div
            key={card.title}
            className="bg-white rounded-lg shadow p-6 hover:shadow-lg transition duration-200"
          >
            <div className="flex items-center justify-between">
              <div>
                <p className="text-gray-500 text-sm">{card.title}</p>
                <p className="text-3xl font-bold text-gray-800 mt-1">{card.value}</p>
              </div>
              <div className={`${card.color} p-3 rounded-full`}>
                <span className="text-white text-2xl">{card.icon}</span>
              </div>
            </div>
          </div>
        ))}
      </div>

      {/* Recent Activity Placeholder */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Recent Students */}
<div className="bg-white rounded-lg shadow p-6">
  <h2 className="text-lg font-semibold text-gray-800 mb-4">Recent Students</h2>
  {recentStudents.length > 0 ? (
    <div className="space-y-3">
      {recentStudents.map((student) => (
        <div key={student.id} className="flex items-center justify-between border-b pb-3 last:border-0">
          <div className="flex items-center space-x-3">
            {student.photo ? (
              <img
                src={`http://localhost:8000/uploads/${student.photo}`}
                alt={student.user?.full_name}
                className="w-10 h-10 rounded-full object-cover"
              />
            ) : (
              <div className="w-10 h-10 bg-blue-100 rounded-full flex items-center justify-center text-blue-600 font-bold">
                {student.user?.full_name?.charAt(0) || 'S'}
              </div>
            )}
            <div>
              <p className="font-medium text-gray-800">{student.user?.full_name || 'Unknown'}</p>
              <p className="text-sm text-gray-500">
                {student.admission_number} • {student.class_name || 'No class'}
              </p>
            </div>
          </div>
          <span className="text-sm text-gray-500">
            {student.created_at ? new Date(student.created_at).toLocaleDateString() : 'N/A'}
          </span>
        </div>
      ))}
    </div>
  ) : (
    <p className="text-gray-500 text-sm">No students added yet.</p>
  )}
</div>
        <div className="bg-white rounded-lg shadow p-6">
          <h2 className="text-lg font-semibold text-gray-800 mb-4">Upcoming Events</h2>
          <p className="text-gray-500 text-sm">No upcoming events.</p>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;
